import { useState } from "react";
import { apiError } from "../api";
import { useCatalog, useComboMutation, useParticipation, useVendorComboTemplates, type AddOn, type CatalogItem, type CatalogTemplate, type Variant } from "../comboApi";
import { useMyListings } from "../../vendor-portal/hooks/useListings";
import { Empty, ErrorText, Panel, StatusPill } from "../ui";
import { vnd } from "../format";

const initial = { id: null as string | null, listingId: "", name: "", basePrice: 0, unit: "Package", minGuests: 1, maxGuests: 2000, regions: "", cancellationPolicy: "Trước 90 ngày: hoàn 100% cọc; 30–89 ngày: hoàn 50%; dưới 30 ngày: không hoàn cọc.", isActive: true, maxBookingsPerDay: 1, variants: [] as Variant[], addOns: [] as AddOn[] };
const initialBundle = { id: null as string | null, name: "", tier: "Popular", style: "Hiện đại", description: "Combo trọn gói một nhà cung cấp", imageUrl: "", region: "", percent: 3 as number | null, selected: {} as Record<string, string> };
function VendorComboRow({ combo, edit }: { combo: CatalogTemplate; edit: () => void }) {
  const archive = useComboMutation(`/api/combos/templates/${combo.id}/archive`);
  return <div className="rounded-xl border border-[var(--line)] p-3"><p className="text-sm"><b>{combo.name}</b> <StatusPill status={combo.moderationStatus} /> · {combo.items.length} hạng mục</p><div className="flex gap-2 mt-2"><button className="btn btn-outline" onClick={edit}>Sửa / gửi duyệt lại</button>{combo.moderationStatus !== "Archived" && <button className="btn btn-outline" disabled={archive.isPending} onClick={() => confirm("Ẩn combo của bạn? Đơn và hợp đồng cũ vẫn được lưu đầy đủ.") && archive.mutate({})}>Ẩn combo</button>}</div><ErrorText>{archive.isError ? apiError(archive.error) : ""}</ErrorText></div>;
}
export function ServiceItemManager() {
  const { data: items = [], error } = useCatalog(); const { data: listings = [] } = useMyListings();
  const { data: participation } = useParticipation();
  const consent = useComboMutation("/api/combos/vendor/participation"); const save = useComboMutation("/api/combos/vendor/items");
  const [form, setForm] = useState<typeof initial | null>(null);
  const [discount, setDiscount] = useState<number | null>(null);
  const [allow, setAllow] = useState<boolean | null>(null);
  const { data: ownCombos = [] } = useVendorComboTemplates(); const saveCombo = useComboMutation("/api/combos/templates");
  const [bundle, setBundle] = useState({ ...initialBundle });
  const approved = items.filter(i => i.moderationStatus === "Approved" && i.isActive);
  const edit = (item: CatalogItem) => setForm({ ...initial, ...item });
  const editBundle = (combo: CatalogTemplate) => setBundle({ ...initialBundle, id: combo.id, name: combo.name, tier: combo.tier, style: combo.style, description: combo.description || "", imageUrl: combo.imageUrl || "", region: combo.region || "", percent: combo.singleVendorDiscount == null ? null : combo.singleVendorDiscount * 100, selected: Object.fromEntries(combo.items.filter(i => i.serviceItemId && approved.some(item => item.id === i.serviceItemId)).map(i => [i.categoryId, i.serviceItemId!])) });
  return <>
    <Panel title="Đồng ý tham gia combo" eyebrow="Dịch vụ & chính sách giảm giá">
      <p className="text-sm muted mb-3">Combo của bạn chỉ gồm dịch vụ của chính NCC bạn, không ghép NCC khác. Sàn không bù tiền giảm giá; ưu đãi không vượt trần đã đồng ý. Bài đăng Active và hồ sơ xác minh là điều kiện bắt buộc.</p>
      <div className="flex flex-wrap gap-3 items-center"><label className="text-sm"><input type="checkbox" checked={allow ?? participation?.allowInCombos ?? false} onChange={e => setAllow(e.target.checked)} /> Cho phép dịch vụ đã duyệt vào combo</label><label className="text-sm">Trần giảm (%) <input aria-label="Trần giảm combo" className="input !w-24" type="number" min={0} max={30} value={discount ?? (participation?.maxComboDiscount ?? 0) * 100} onChange={e => setDiscount(+e.target.value)} /></label><button className="btn btn-primary" disabled={consent.isPending} onClick={() => consent.mutate({ allowInCombos: allow ?? participation?.allowInCombos ?? false, maxComboDiscount: (discount ?? (participation?.maxComboDiscount ?? 0) * 100) / 100 })}>Lưu thỏa thuận</button></div><ErrorText>{consent.isError ? apiError(consent.error) : ""}</ErrorText>
    </Panel>
    <Panel title="Dịch vụ, biến thể & món kèm" action={<button className="btn btn-outline" onClick={() => setForm({ ...initial })}>Thêm dịch vụ combo</button>}>
      <ErrorText>{error ? apiError(error) : ""}</ErrorText>
      {items.length === 0 ? <Empty>Chưa có dịch vụ combo. Tạo từ một bài đăng đã Active rồi gửi Moderator duyệt.</Empty> : <div className="grid sm:grid-cols-2 gap-3">{items.map(i => <button key={i.id} className="kiosk-option text-left" onClick={() => edit(i)}><b>{i.name}</b> <StatusPill status={i.moderationStatus} /><p className="text-sm">{vnd(i.basePrice)} / {i.unit} · {i.regions}</p><p className="text-xs muted">{i.minGuests}–{i.maxGuests} khách; {i.variants.length} biến thể, {i.addOns.length} món kèm{!i.isActive && " · tạm tắt"}</p>{i.reviewNote && <p className="text-xs">{i.reviewNote}</p>}</button>)}</div>}
      {form && <div className="rounded-xl border border-[var(--line)] p-4 grid sm:grid-cols-3 gap-3 mt-4">
        <label className="sm:col-span-2"><span className="label">Bài đăng Active</span><select className="input" value={form.listingId} disabled={!!form.id} onChange={e => setForm({ ...form, listingId: e.target.value })}><option value="">Chọn bài đăng</option>{listings.filter(l => l.status === "Active").map(l => <option key={l.id} value={l.id}>{l.title}</option>)}</select></label>
        <label><span className="label">Tên gói/item</span><input className="input" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} /></label>
        <label><span className="label">Giá cơ bản (đ)</span><input className="input" type="number" min={0} value={form.basePrice} onChange={e => setForm({ ...form, basePrice: +e.target.value })} /></label>
        <label><span className="label">Đơn vị</span><select className="input" value={form.unit} onChange={e => setForm({ ...form, unit: e.target.value })}><option value="Package">Gói</option><option value="Table">Bàn (10 khách)</option><option value="Guest">Khách</option><option value="Hour">Giờ</option></select></label>
        <label><span className="label">Số đơn tối đa mỗi ngày</span><input className="input" type="number" min={1} max={100} value={form.maxBookingsPerDay} onChange={e => setForm({ ...form, maxBookingsPerDay: +e.target.value })} /></label>
        <label><span className="label">Tối thiểu khách</span><input className="input" type="number" value={form.minGuests} onChange={e => setForm({ ...form, minGuests: +e.target.value })} /></label>
        <label><span className="label">Tối đa khách</span><input className="input" type="number" value={form.maxGuests} onChange={e => setForm({ ...form, maxGuests: +e.target.value })} /></label>
        <label><span className="label">Khu vực (cách bằng dấu phẩy; * toàn quốc)</span><input className="input" value={form.regions} onChange={e => setForm({ ...form, regions: e.target.value })} /></label>
        <label className="sm:col-span-3"><span className="label">Chính sách hủy</span><textarea className="input" value={form.cancellationPolicy} onChange={e => setForm({ ...form, cancellationPolicy: e.target.value })} /></label>
        <div className="sm:col-span-3"><b className="text-sm">Biến thể (cộng/trừ trên giá mỗi đơn vị)</b>{form.variants.map((v, index) => <div key={index} className="flex gap-2 mt-2"><input className="input" aria-label="Tên biến thể" placeholder="VD: 2 máy quay + flycam" value={v.name} onChange={e => setForm({ ...form, variants: form.variants.map((x, i) => i === index ? { ...x, name: e.target.value } : x) })} /><input className="input !w-40" aria-label="Giá chênh biến thể" type="number" value={v.priceDelta} onChange={e => setForm({ ...form, variants: form.variants.map((x, i) => i === index ? { ...x, priceDelta: +e.target.value } : x) })} /><button className="underline text-xs" onClick={() => setForm({ ...form, variants: form.variants.filter((_, i) => i !== index) })}>Bỏ</button></div>)}<button className="chip mt-2" onClick={() => setForm({ ...form, variants: [...form.variants, { name: "", priceDelta: 0 }] })}>+ Biến thể</button></div>
        <div className="sm:col-span-3"><b className="text-sm">Món kèm</b>{form.addOns.map((a, index) => <div key={index} className="flex flex-wrap gap-2 mt-2"><input className="input !w-48" aria-label="Tên món kèm" placeholder="VD: Photobooth" value={a.name} onChange={e => setForm({ ...form, addOns: form.addOns.map((x, i) => i === index ? { ...x, name: e.target.value } : x) })} /><input className="input !w-40" aria-label="Giá món kèm" type="number" min={0} value={a.price} onChange={e => setForm({ ...form, addOns: form.addOns.map((x, i) => i === index ? { ...x, price: +e.target.value } : x) })} /><label className="text-xs"><input type="checkbox" checked={a.perUnit} onChange={e => setForm({ ...form, addOns: form.addOns.map((x, i) => i === index ? { ...x, perUnit: e.target.checked } : x) })} /> Nhân số lượng</label><button className="underline text-xs" onClick={() => setForm({ ...form, addOns: form.addOns.filter((_, i) => i !== index) })}>Bỏ</button></div>)}<button className="chip mt-2" onClick={() => setForm({ ...form, addOns: [...form.addOns, { name: "", price: 0, perUnit: false }] })}>+ Món kèm</button></div>
        <label className="text-sm"><input type="checkbox" checked={form.isActive} onChange={e => setForm({ ...form, isActive: e.target.checked })} /> Đang kinh doanh</label>
        <div className="sm:col-span-3"><ErrorText>{save.isError ? apiError(save.error) : ""}</ErrorText><div className="flex gap-2 justify-end"><button className="btn btn-outline" onClick={() => setForm(null)}>Đóng</button><button className="btn btn-outline" disabled={save.isPending} onClick={() => save.mutate({ ...form, submitForApproval: false }, { onSuccess: () => setForm(null) })}>Lưu nháp</button><button className="btn btn-primary" disabled={save.isPending} onClick={() => save.mutate({ ...form, submitForApproval: true }, { onSuccess: () => setForm(null) })}>Gửi duyệt</button></div></div>
      </div>}
    </Panel>
    <Panel title="Combo trọn gói của NCC" eyebrow="Mọi hạng mục đều thuộc NCC của bạn">
      <div className="grid gap-2 mb-3">{ownCombos.map(t => <VendorComboRow key={t.id} combo={t} edit={() => editBundle(t)} />)}</div>
      <p className="text-sm mb-3">{bundle.id ? "Đang chỉnh combo đã chọn; gửi lại sẽ chờ kiểm duyệt." : "Tạo combo mới từ danh mục dịch vụ của bạn."} Khách chỉ được đổi sang dịch vụ của chính NCC bạn. <button className="underline" onClick={() => setBundle({ ...initialBundle })}>Tạo combo mới</button></p>
      <div className="grid sm:grid-cols-2 gap-3"><input aria-label="Tên combo NCC" className="input" placeholder="Tên combo trọn gói" value={bundle.name} onChange={e => setBundle({ ...bundle, name: e.target.value })} /><input aria-label="Phong cách combo NCC" className="input" placeholder="Phong cách" value={bundle.style} onChange={e => setBundle({ ...bundle, style: e.target.value })} /><input aria-label="Khu vực combo NCC" className="input" placeholder="Khu vực (* = toàn quốc)" value={bundle.region} onChange={e => setBundle({ ...bundle, region: e.target.value })} /><label className="text-sm">Mức giảm combo (%) <input className="input" type="number" min={0} max={(participation?.maxComboDiscount ?? 0) * 100} value={bundle.percent ?? ""} placeholder="Để trống: quy tắc chung" onChange={e => setBundle({ ...bundle, percent: e.target.value === "" ? null : +e.target.value })} /></label>
        <label className="text-sm">Phân khúc<select className="input" value={bundle.tier} onChange={e => setBundle({ ...bundle, tier: e.target.value })}><option value="Saving">Tiết kiệm</option><option value="Popular">Phổ biến</option><option value="Luxury">Sang trọng</option></select></label><input aria-label="Ảnh combo NCC" className="input" placeholder="URL ảnh combo" value={bundle.imageUrl} onChange={e => setBundle({ ...bundle, imageUrl: e.target.value })} /><textarea aria-label="Mô tả combo NCC" className="input sm:col-span-2" placeholder="Mô tả nội dung gói" value={bundle.description} onChange={e => setBundle({ ...bundle, description: e.target.value })} />
        {[...new Set(approved.map(i => i.categoryId))].map(category => <select key={category} className="input" value={bundle.selected[category] || ""} onChange={e => setBundle({ ...bundle, selected: { ...bundle.selected, [category]: e.target.value } })}><option value="">Chọn dịch vụ mặc định/ngành (hoặc bỏ)</option>{approved.filter(i => i.categoryId === category).map(i => <option key={i.id} value={i.id}>{i.name}</option>)}</select>)}
      </div><ErrorText>{saveCombo.isError ? apiError(saveCombo.error) : ""}</ErrorText><button className="btn btn-primary mt-3" disabled={saveCombo.isPending || !bundle.name || !Object.values(bundle.selected).some(Boolean)} onClick={() => saveCombo.mutate({ id: bundle.id, name: bundle.name, tier: bundle.tier, style: bundle.style, region: bundle.region || "*", description: bundle.description, imageUrl: bundle.imageUrl || null, isActive: true, sortOrder: 0, singleVendorDiscount: bundle.percent == null ? null : bundle.percent / 100, items: Object.entries(bundle.selected).filter(([, id]) => !!id && approved.some(item => item.id === id)).map(([categoryId, serviceItemId]) => ({ categoryId, serviceItemId, listingId: approved.find(i => i.id === serviceItemId)!.listingId, isOptional: false, allowedItemIds: approved.filter(i => i.categoryId === categoryId).map(i => i.id) })) }, { onSuccess: () => setBundle({ ...initialBundle }) })}>{bundle.id ? "Lưu & gửi duyệt lại" : "Gửi duyệt combo NCC"}</button>
    </Panel>
  </>;
}
